/* Executable, bounded teaching models; not an interpreter for arbitrary C. */
"use strict";
(()=>{
const esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
const copy=x=>JSON.parse(JSON.stringify(x));
const t=(x,y,s,cls='rc-label')=>`<text x="${x}" y="${y}" class="${cls}">${esc(s)}</text>`;
const rect=(x,y,w,h,fill='#ecf3f6')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${fill}" stroke="#7f9baa"/>`;
function arrow(x1,y1,x2,y2,color='#527b8d') {const a=Math.atan2(y2-y1,x2-x1),ux=Math.cos(a),uy=Math.sin(a),bx=x2-8*ux,by=y2-8*uy;return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2"/><polygon points="${x2},${y2} ${bx-3*uy},${by+3*ux} ${bx+3*uy},${by-3*ux}" fill="${color}"/>`;}
function stackSVG(s,title){let b=t(35,32,title)+t(35,74,'Live invocations: suspended parents retain their continuations.');
 s.stack.forEach((f,i)=>{const y=108+i*58,fill=i===s.stack.length-1?'#d6edf0':'#edf2f6';b+=`<g data-entity="frame-${f.id}">${rect(35,y,430,44,fill)}${t(52,y+28,f.label,'rc-code')}</g>`;if(i)b+=arrow(475,y-14,475,y+10);});
 b+=t(540,133,'Requests entered: '+s.calls)+t(540,171,'Active frames: '+s.stack.length)+t(540,209,'Maximum depth: '+s.depth)+t(540,247,'Arithmetic / moves: '+s.ops);
 if(s.output.length)b+=t(540,291,'Output: '+s.output.join(' '));if(s.returned!==null)b+=`<g data-entity="return-value">${rect(540,320,415,48,'#e5eee0')}${t(558,350,'Returned value: '+s.returned,'rc-code')}</g>`;
 if(s.cache){b+=t(540,407,'Completed cache entries (not pending calls)');Object.entries(s.cache).forEach(([k,v],i)=>{let x=540+(i%4)*104,y=430+Math.floor(i/4)*64;b+=`<g data-entity="cache-${k}">${rect(x,y,92,48,'#e5eee0')}${t(x+12,y+29,k+': '+v,'rc-code')}</g>`;});}
 if(s.interval)b+=t(540,590,'Current interval: ['+s.interval.join(', ')+')');
 if(s.chosen)b+=t(540,590,'Current choice: ['+s.chosen.join(', ')+']');
 return svg(b,Math.max(680,150+s.stack.length*58),'recursion-stack');}
function treeSVG(s,title){let b=t(35,32,title)+t(35,74,'Each node is one invocation; arrows connect actual parent and child ports.');const nodes=s.nodes,depth=Math.max(0,...nodes.map(q=>q.d));
 for(const q of nodes){if(q.parent!==null){const p=nodes.find(x=>x.id===q.parent);b+=arrow(p.x,p.d*100+148,q.x,q.d*100+108);}}
 for(const q of nodes){const y=q.d*100+108,fill=q.done?'#e2eedf':q.id===s.stack.at(-1)?.id?'#d3eaf0':'#eff3f7';b+=`<g data-entity="node-${q.id}">${rect(q.x-24,y,48,40,fill)}${t(q.x-12,y+26,String(q.n),'rc-math')}</g>`;}
 b+=t(35,depth*100+196,'Entered '+s.calls+' invocations; peak live depth '+s.depth+'; additions '+s.ops+'.');
 if(s.returned!==null)b+=t(35,depth*100+236,'Most recent returned value: '+s.returned);
 return svg(b,depth*100+280,'call-tree');}
function intervalSVG(s,title){let b=t(35,32,title)+t(35,74,'Only the highlighted half-open interval remains under consideration.');const a=s.array,w=820/Math.max(1,a.length),l=s.interval[0],r=s.interval[1];a.forEach((v,i)=>{const x=70+i*w;b+=`<g data-entity="cell-${i}">${rect(x,145,w-8,56,i>=l&&i<r?'#d7edf0':'#f1f3f5')}${t(x+12,181,v,'rc-code')}${t(x+12,128,i,'rc-math')}</g>`;});b+=t(70,270,'Bounds: ['+l+', '+r+'); remaining length '+(r-l))+t(70,314,'Invocations '+s.calls+'; comparisons '+s.ops+'; peak depth '+s.depth);if(s.returned!==null)b+=t(70,368,'Result: '+s.returned);return svg(b,430,'interval-shrink');}
function hanoiSVG(s,title){let b=t(35,32,title)+t(35,74,'Disk order is verified before every move; transit is not a settled puzzle state.');const xs=[180,500,820],floor=370,colors=['#82b3c2','#9cc7b5','#c6b0d2','#dfc294'];for(let p=0;p<3;p++){b+=`<line x1="${xs[p]}" y1="130" x2="${xs[p]}" y2="${floor}" stroke="#9badb5" stroke-width="7"/><line x1="${xs[p]-140}" y1="${floor+8}" x2="${xs[p]+140}" y2="${floor+8}" stroke="#728d9a" stroke-width="5"/>`+t(xs[p]-35,420,['Source','Spare','Target'][p]);s.pegs[p].forEach((d,i)=>{const w=64+d*36,y=floor-(i+1)*34;b+=`<g data-entity="disk-${d}">${rect(xs[p]-w/2,y,w,30,colors[(d-1)%4])}${t(xs[p]-5,y+21,d,'rc-math')}</g>`;});}
 if(s.flying){const d=s.flying.disk,w=64+d*36;b+=`<g data-entity="disk-${d}">${rect(s.flying.x-w/2,s.flying.y,w,30,colors[(d-1)%4])}${t(s.flying.x-5,s.flying.y+21,d,'rc-math')}</g>`;}
 b+=t(35,478,'Completed legal moves: '+s.moves+'; phase: '+s.phase)+t(35,524,'Invocations entered '+s.calls+'; active depth '+s.stack.length+'; maximum '+s.depth);
 return svg(b,570,'hanoi-pegs');}
function kochPoints(k,a=[70,340],b=[930,340]){if(k===0)return[a,b];const dx=(b[0]-a[0])/3,dy=(b[1]-a[1])/3,p=[a[0]+dx,a[1]+dy],r=[a[0]+2*dx,a[1]+2*dy],q=[p[0]+dx/2+Math.sqrt(3)*dy/2,p[1]+dy/2-Math.sqrt(3)*dx/2];return[[a,p],[p,q],[q,r],[r,b]].flatMap((v,i)=>kochPoints(k-1,...v).slice(i?1:0));}
function svg(body,h,kind){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" data-kind="${kind}" aria-label="A checked recursive execution checkpoint">${body}</svg>`;}
const guides={factorial:['if (n == 0) return 1;','child = fact(n - 1);','return n * child;'],around:['if (n == 0) return;','print(n);','around(n - 1);','print(n);'],fib:['if (n <= 1) return n;','left = fib(n - 1);','right = fib(n - 2);','return left + right;'],memo:['if (cache contains n) return cache[n];','left = fib(n - 1);','right = fib(n - 2);','cache[n] = left + right;','return cache[n];'],digits:['if (n < 10) return n;','child = digits(floor(n / 10));','return n % 10 + child;'],gcd:['if (b == 0) return a;','return gcd(b, a % b);'],power:['if (e == 0) return 1;','if (e == 1) return a;','h = power(a, floor(e / 2));','return even(e) ? h*h : a*h*h;'],palindrome:['if (r-l <= 1) return true;','if (a[l] != a[r-1]) return false;','return palindrome(a,l+1,r-1);'],binary:['if (l == r) return false;','m = l + floor((r-l)/2);','if (a[m] == target) return true;','return search(the strictly shorter interval);'],subsets:['if (i == n) emit(chosen);','recurse excluding i;','append(i); recurse including i;','remove the appended i;'],stride:['if (n < 0) return;','b[i] = a[n];','store(n-2,i+1);'],hanoi:['if (n == 0) return;','hanoi(n-1,source,spare,target);','move one exposed disk;','hanoi(n-1,spare,target,source);'],koch:['if (order == 0) draw one segment;','replace by four one-third segments;','recurse on the four oriented segments;']};
function makeModel(id,title,spec){const s=copy(spec),op=s.operation,n=Number(s.n??3);if(!Number.isInteger(n)||n<0||n>8)throw Error('n must be an integer between zero and eight.');if(!guides[op])throw Error('Choose a supported recursive algorithm.');if(op==='fib'&&n>5)throw Error('The full Fibonacci tree is limited to n <= 5 for legible nodes.');if(op==='hanoi'&&n>4)throw Error('Hanoi uses at most four disks.');if(op==='subsets'&&n>4)throw Error('Subset enumeration uses at most four positions.');if(op==='koch'&&n>3)throw Error('Koch geometry uses at most three replacement levels.');
 const st={calls:0,depth:0,ops:0,stack:[],nodes:[],output:[],returned:null};if(op==='memo')st.cache={0:0,1:1};const frames=[];let serial=0;let invariant='Every child satisfies the smaller-state contract; suspended parents retain their pending work.';
 function frame(caption,line=0,extra={}){Object.assign(st,extra);const snapshot=copy(st),prior=frames.at(-1)?.snapshot;const checks=[{expression:'Live depth <= observed maximum depth',result:st.stack.length<=st.depth},{expression:'Every invocation has a unique frame identity',result:new Set(st.stack.map(f=>f.id)).size===st.stack.length}];
 let drawing=op==='fib'?treeSVG(st,title):['palindrome','binary'].includes(op)?intervalSVG(st,title):op==='hanoi'?hanoiSVG(st,title):stackSVG(st,title);
 frames.push({snapshot,svg:drawing,caption,formula:`C=${st.calls},\\quad D=${st.depth},\\quad A=${st.ops}`,teaching:{operation:caption,why:invariant,checks,changes:['calls','ops','returned','output','cache','interval','chosen','pegs','phase'].filter(k=>JSON.stringify(prior?.[k])!==JSON.stringify(st[k])&&st[k]!==undefined).map(k=>({field:k,before:prior?.[k]??'not yet established',after:copy(st[k])})),currentState:snapshot,initial:spec,reading:invariant,guide:guides[op],activeLine:line,mode:'Checked '+op+' execution'}});}
 function enter(label,arg,lo=60,hi=940){const parent=st.stack.at(-1)?.id??null,f={id:serial++,label,n:arg,parent,d:st.stack.length,x:(lo+hi)/2,done:false};st.stack.push(f);st.nodes.push(copy(f));st.calls++;st.depth=Math.max(st.depth,st.stack.length);st.returned=null;frame('Enter '+label+'; save the caller continuation.',op==='memo'?0:0);return f;}
 function leave(value,line){st.returned=value;st.nodes.find(q=>q.id===st.stack.at(-1).id).done=true;frame('Complete this invocation; return '+value+' to its waiting caller.',line);st.stack.pop();return value;}
 function scalar(x,lo=60,hi=940){const f=enter(op+'('+x+')',x,lo,hi);let v;if(op==='factorial'){v=x===0?1:scalar(x-1)*x;if(x>0)st.ops++;return leave(v,x?2:0);}if(op==='around'){if(x>0){st.output.push(x);frame('Emit '+x+' before the child call.',1);scalar(x-1);st.output.push(x);frame('Emit '+x+' after its child has returned.',3);}return leave(0,0);}if(op==='digits'){v=x<10?x:scalar(Math.floor(x/10))+x%10;if(x>=10)st.ops++;return leave(v,x<10?0:2);}if(op==='fib'||op==='memo'){if(op==='memo'&&Object.hasOwn(st.cache,x)){frame('Cache hit at state '+x+'; no child subtree is evaluated.',0);return leave(st.cache[x],0);}if(x<=1)return leave(x,0);let mid=(lo+hi)/2,left=scalar(x-1,lo,mid),right=scalar(x-2,mid,hi);v=left+right;st.ops++;if(op==='memo'){st.cache[x]=v;frame('Store a completed answer for state '+x+'.',3);}return leave(v,op==='memo'?4:3);}throw Error('Unknown scalar operation.');}
 let result;
 if(['factorial','around','fib','memo'].includes(op))result=scalar(n);
 if(op==='digits'){let x=Number(s.value??738);if(!Number.isSafeInteger(x)||x<0||x>99999999)throw Error('Digit input must be an integer from zero to 99,999,999.');result=scalar(x);}
 if(op==='gcd'){let a=Number(s.a??1071),b=Number(s.b??462);if(![a,b].every(x=>Number.isSafeInteger(x)&&x>=0&&x<=10000))throw Error('GCD inputs must be nonnegative integers at most 10,000.');function g(a,b){enter('gcd('+a+', '+b+')',b);if(b===0)return leave(a,0);st.ops++;const r=a%b;frame('Remainder '+r+' is strictly below positive divisor '+b+'.',1);return leave(g(b,r),1);}result=g(a,b);}
 if(op==='power'){const a=Number(s.a??2),e=Number(s.exponent??13);if(!Number.isInteger(a)||a<0||a>3||!Number.isInteger(e)||e<0||e>13)throw Error('Power base is zero to three; exponent is zero to thirteen.');function p(e){enter('power('+a+', '+e+')',e);if(e<=1)return leave(e===0?1:a,e);const h=p(Math.floor(e/2));st.ops+=1+(e%2);return leave(h*h*(e%2?a:1),3);}result=p(e);}
 if(op==='palindrome'||op==='binary'){st.array=op==='palindrome'?[...String(s.text??'abccba')]:s.array??[1,3,5,7,9,11,13];if(st.array.length>8||!st.array.length&&op==='binary'&&s.array===undefined)throw Error('Use at most eight array elements.');if(op==='palindrome'&&!/^[\x20-\x7e]*$/.test(s.text??'abccba'))throw Error('The byte palindrome model accepts printable ASCII only.');if(op==='binary'&&(!st.array.every(Number.isFinite)||st.array.some((x,i)=>i&&x<st.array[i-1])))throw Error('Binary-search values must be finite and sorted.');const target=Number(s.target??8);if(op==='binary'&&!Number.isFinite(target))throw Error('Target must be finite.');function p(l,r){st.interval=[l,r];enter(op+'(['+l+', '+r+'))',r-l);if(op==='palindrome'){if(r-l<=1)return leave(true,0);st.ops++;frame('Compare the two content endpoints.',1);if(st.array[l]!==st.array[r-1])return leave(false,1);return leave(p(l+1,r-1),2);}if(l===r)return leave(false,0);const m=l+Math.floor((r-l)/2);st.ops++;frame('Compare midpoint index '+m+' with target '+target+'.',1);if(st.array[m]===target)return leave(true,2);return leave(target<st.array[m]?p(l,m):p(m+1,r),3);}result=p(0,st.array.length);}
 if(op==='subsets'){invariant='Before returning, restore exactly the chosen prefix present on entry.';st.chosen=[];const outs=[];function visit(i){enter('subsets(i='+i+')',i);if(i===n){outs.push(copy(st.chosen));frame('Emit completed choice ['+st.chosen.join(', ')+'].',0);}else{visit(i+1);st.chosen.push(i);frame('Include position '+i+'; the following child sees this prefix.',2);visit(i+1);st.chosen.pop();frame('Undo position '+i+' and restore the parent prefix.',3);}return leave('prefix restored',3);}visit(0);result=outs;}
 if(op==='stride'){st.array=Array.from({length:n},(_,i)=>i);const out=[];function p(x,i){enter('store('+x+', '+i+')',x);if(x<0)return leave('stop',0);out.push(st.array[x]);st.ops++;st.output=copy(out);frame('Copy source index '+x+' into destination index '+i+'.',1);return leave(p(x-2,i+1),2);}p(n-1,0);result=out;}
 if(op==='hanoi'){invariant='Only a top disk moves, and it is lowered onto an empty peg or a larger top disk.';st.pegs=[Array.from({length:n},(_,i)=>n-i),[],[]];st.moves=0;st.phase='settled';function h(k,a,b,c){enter('Hanoi('+k+', '+a+' to '+b+')',k);if(k){h(k-1,a,c,b);const disk=st.pegs[a].at(-1);if(disk!==k||st.pegs[b].length&&st.pegs[b].at(-1)<disk)throw Error('Illegal disk move.');st.pegs[a].pop();const xs=[180,500,820];st.flying={disk,x:xs[a],y:370-st.pegs[a].length*34-34};st.phase='lift';frame('Lift top disk '+disk+' from peg '+a+'.',2);st.flying.y=94;frame('Disk '+disk+' is above every peg and settled tower.',2);st.flying.x=xs[b];st.phase='transfer';frame('Transfer the lifted disk to peg '+b+'.',2);st.flying.y=370-(st.pegs[b].length+1)*34;st.phase='lower';frame('Lower disk '+disk+' toward its legal destination.',2);st.pegs[b].push(disk);st.flying=null;st.moves++;st.ops++;st.phase='settled';frame('Complete legal move '+st.moves+'.',2);h(k-1,c,b,a);}return leave('subtower complete',k?3:0);}h(n,0,2,1);result=copy(st.pegs);}
 if(op==='koch'){invariant='Each segment is replaced by four oriented segments of one-third its length.';for(let k=0;k<=n;k++){const ps=kochPoints(k);st.calls=(4**(k+1)-1)/3;st.depth=k+1;st.ops=4**k;st.stack=[];frame('Completed replacement order '+k+'; each visible segment is a drawing primitive.',k?2:0);frames.at(-1).svg=svg(t(35,32,title)+t(35,74,'Order '+k+': '+4**k+' segments; relative total length '+(4/3)**k)+`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#34758d" stroke-width="3"/>`+t(35,415,'Koch geometry: each forward replacement keeps its endpoints connected.'),470,'koch-geometry');frames.at(-1).snapshot.order=k;}result={segments:4**n,lengthFactor:(4/3)**n};}
 const kind=op==='fib'?'call-tree':op==='hanoi'?'hanoi-pegs':op==='koch'?'koch-geometry':['palindrome','binary'].includes(op)?'interval-shrink':'recursion-stack';return{id,title,kind,invariant,spec,frames,result,counts:{calls:st.calls,depth:st.depth,ops:st.ops}};
}
if(typeof module!=='undefined')module.exports={makeModel,kochPoints};
if(typeof document==='undefined')return;
function mount(host,m){return AdvancedSimulations.mount(host,m,{topic:"p_recursion",prefix:"rc"});}





const controls=()=>'<div class="rc-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0" aria-label="Recursive execution checkpoint"></label></div><div class="rc-stage"></div><p class="rc-caption"></p><p data-progress></p><div class="rc-formula formula-block"></div><div class="rc-print"></div>';
async function boot(){const d=await(await fetch('p_recursion-models.json')).json();globalThis.RecursionPlayers=[];for(const host of document.querySelectorAll('[data-rc-model]')){const m=d.models.find(m=>m.id===host.dataset.rcModel);if(!m)throw Error('Missing recursion model.');RecursionPlayers.push(mount(host,m));}const form=document.querySelector('#rc-form'),out=document.querySelector('#rc-output'),error=document.querySelector('#rc-error');let current=null;form.addEventListener('submit',event=>{event.preventDefault();try{const f=form.elements,s={operation:f.operation.value,n:Number(f.n.value),a:Number(f.a.value),b:Number(f.b.value),exponent:Number(f.exponent.value),value:Number(f.value.value),text:f.text.value,target:Number(f.target.value)},m=makeModel('editable-recursion','Your checked '+s.operation+' execution',s);for(const q of m.frames){q.formulaHtml='<math xmlns="http://www.w3.org/1998/Math/MathML"><mtext>entered calls '+q.snapshot.calls+'; peak depth '+q.snapshot.depth+'; counted operations '+q.snapshot.ops+'</mtext></math>';q.teaching.checks=q.teaching.checks.map(c=>({mathHtml:'<p>'+esc(c.expression)+'</p>',result:c.result}));}current?.dispose();out.innerHTML='<section class="rc-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section><section class="lab-results"><h3>Checked result and counting convention</h3><pre>'+esc(JSON.stringify({result:m.result,counts:m.counts},null,2))+'</pre></section>';current=mount(out.firstChild,m);globalThis.RecursionLab=current;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}boot().catch(e=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='Recursion laboratory failed: '+e.message;document.querySelector('.lesson').prepend(p);throw e;});
})();
